Database.Load:
      var index = 0;
	  var portfolioPKey = "";  
	  var espPKey = "";
      var additionalCond = "";

	  if(Utils.isDefined(jsonQuery.portfolioPKey)){
        portfolioPKey =  Utils.convertForDBParam(jsonQuery.portfolioPKey, "DomPKey");
        additionalCond += "AND cgf_Especialidad_Cartera__c.cgf_Cartera__c = #portfolioPKey# ";
	  }
	  if(Utils.isDefined(jsonQuery.espPKey)){
        espPKey = Utils.convertForDBParam(jsonQuery.espPKey, "DomPKey");
        additionalCond += "AND cgf_Especialidad_Cartera__c.Id = #espPKey# ";
      }

      var sqlParams = {portfolioPKey, espPKey};

      var sqlStmt = "SELECT ";
      sqlStmt += "cgf_Especialidad_Cartera__c.Id AS pKey, ";
      sqlStmt += "cgf_Especialidad_Cartera__c.Name AS espName, ";
      sqlStmt += "cgf_Especialidad_Cartera__c.cgf_Cartera__c AS portfolioPKey, ";
      sqlStmt += "cgf_Especialidad_Cartera__c.Name as espName ";
      sqlStmt += "FROM cgf_Especialidad_Cartera__c ";
      sqlStmt += "WHERE ";
      sqlStmt += "cgf_Especialidad_Cartera__c.IsDeleted = '0' ";
      sqlStmt += additionalCond;

      return Utils.replaceMacrosParam(sqlStmt, sqlParams);
